figure;
hold on;
plot(n, t_bs,  '-o', 'DisplayName', 'Bubble sort');
plot(n, t_is,  '-s', 'DisplayName', 'Insertion sort');
plot(n, t_ss,  '-^', 'DisplayName', 'Selection sort');
