semilogy(n, t_qs+eps,  '-x', 'DisplayName', 'Quick sort');
semilogy(n, t_std+eps, '-+', 'DisplayName', 'std::sort');
hold off;

xlabel('Dimensione vettore');
ylabel('Tempo medio (ms) - scala log');
title('Confronto algoritmi di ordinamento (scala logaritmica)');
legend('Location', 'northwest');
grid on;
set(gca, 'YScale', 'log');